import 'package:flutter/material.dart';

/// Satu chapter Sirah Nabawiyah — struktur ringkas untuk reader.
class SirahChapter {
  final int number;
  final String title;
  final String subtitle;
  final String period; // rentang waktu / tahun
  final IconData icon;
  final String body; // paragraf-paragraf, dipisah "\n\n"
  const SirahChapter({
    required this.number,
    required this.title,
    required this.subtitle,
    required this.period,
    required this.icon,
    required this.body,
  });

  /// Estimasi durasi baca ~200 kpm.
  int get estimatedMinutes {
    final words = body.split(RegExp(r'\s+')).length;
    final m = (words / 200).ceil();
    return m < 1 ? 1 : m;
  }
}

